package com.honorablemobile
import org.junit.Assert.*
import org.junit.Test
class VideoCaptionWorksheetTest {
 private fun clips()=listOf(VideoSegment(0,5000,speed=1.5f,title="Keep title",fadeEdges=true,grade=VideoGrade(exposure=.5f),volume=.3f,audioFade=true,captions=listOf(VideoCaption(0,1000,"Hello"),VideoCaption(2000,3000,"Second\\line\nThird")),captionSourceUri="content://synthetic/subtitles"),VideoSegment(1000,5000,sourceId="other",captions=listOf(VideoCaption(1000,2000,"Other"))))
 private fun changed(clips:List<VideoSegment>)=VideoCaptionWorksheet.export(clips).replace("1.1\tHello","1.1\tBonjour")
 @Test fun worksheetHasStableKeysEscapedTextAndNoSourceMetadataUris(){
  val c=clips();val text=VideoCaptionWorksheet.export(c);assertTrue(text.startsWith("NOBLE-CAPTION-TEXT/1 "));assertEquals(4,text.lines().size);assertTrue(text.contains("1.2\tSecond\\\\line\\nThird"));assertTrue(text.contains("2.1\tOther"));assertFalse(text.contains("content://"));assertEquals(text,VideoCaptionWorksheet.export(c))
 }
 @Test fun replacementsPreserveEveryTimingSourceAppearanceAndProvenance(){val c=clips();val r=VideoCaptionWorksheet.prepare(c,changed(c));assertEquals(1,r.changedCues);assertEquals("Bonjour",r.clips[0].captions[0].text);assertEquals(c[0].copy(captions=listOf(c[0].captions[0].copy(text="Bonjour"),c[0].captions[1])),r.clips[0]);assertSame(c[1],r.clips[1]);assertEquals("Hello",c[0].captions[0].text)}
 @Test fun unicodeLineBreaksAndLiteralEscapesSurviveTranslation(){val c=clips();val text=VideoCaptionWorksheet.export(c).replace("1.1\tHello","1.1\tこんにちは 😀\\nمساء الخير\\\\n");val r=VideoCaptionWorksheet.prepare(c,text);assertEquals("こんにちは 😀\nمساء الخير\\n",r.clips[0].captions[0].text);assertEquals(c[0].captions[1],r.clips[0].captions[1])}
 @Test fun reordersRowsAndAcceptsCrLfAndTrailingBlankRows(){val c=clips();val rows=changed(c).lines();val reordered=(listOf(rows[0])+rows.drop(1).reversed()+listOf("","")).joinToString("\r\n");assertEquals(VideoCaptionWorksheet.prepare(c,changed(c)),VideoCaptionWorksheet.prepare(c,reordered))}
 @Test fun duplicateMissingUnknownMalformedAndEmptyKeysFail(){val c=clips();val text=changed(c);val rows=text.lines();for(w in listOf(text+"\n"+rows[1],rows.dropLast(1).joinToString("\n"),text.replace("1.1\t","7.1\t"),text.replace("1.1\t","1.1 "),text.replace("1.1\t","\t"),text+"\n9.1\tUnexpected"))assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.prepare(c,w)}}
 @Test fun malformedEscapesRawTabsControlCodesAndInvalidUnicodeFail(){val c=clips();for(value in listOf("bad\\q","bad\\","bad\ttext","bad\u0000text","\ud800","bad\rtext")){val text=changed(c).replace("Bonjour",value);assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.prepare(c,text)}}}
 @Test fun invalidCueTextOrNoChangesCannotProducePartialResult(){val c=clips();for(value in listOf("","   ","x".repeat(241),"a\\nb\\nc\\nd")){assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.prepare(c,changed(c).replace("Bonjour",value))}};assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.prepare(c,VideoCaptionWorksheet.export(c))};assertEquals("Hello",c[0].captions[0].text)}
 @Test fun changedOriginalTextTimingsSourceSpeedOrderOrProvenanceInvalidateHeader(){val c=clips();val text=changed(c);val changes=listOf(c.reversed(),listOf(c[0].copy(startMs=1),c[1]),listOf(c[0].copy(speed=2f),c[1]),listOf(c[0].copy(sourceId="replaced"),c[1]),listOf(c[0].copy(captionSourceUri="content://synthetic/replaced"),c[1]),listOf(c[0].copy(captions=listOf(c[0].captions[0].copy(text="Original changed"),c[0].captions[1])),c[1]),listOf(c[0].copy(captions=listOf(c[0].captions[0].copy(endMs=1001),c[0].captions[1])),c[1]));for(next in changes)assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.prepare(next,text)}}
 @Test fun unrelatedLookChangesCanKeepWorksheetBecauseOnlyTextIsReplaced(){val c=clips();val next=listOf(c[0].copy(grade=VideoGrade(saturation=.5f),title="New title"),c[1]);val r=VideoCaptionWorksheet.prepare(next,changed(c));assertEquals(next[0].grade,r.clips[0].grade);assertEquals("New title",r.clips[0].title);assertEquals("Bonjour",r.clips[0].captions[0].text)}
 @Test fun forgedOrUnsupportedHeaderIsRefused(){val c=clips();for(w in listOf(changed(c).replace("/1 ","/2 "),changed(c).replaceFirst(Regex("[a-f0-9]{64}"),"0".repeat(64))," "+changed(c)))assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.prepare(c,w)}}
 @Test fun exportRefusesEmptyOrOversizedProjectAndImportBoundsAreStrict(){assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.export(emptyList())};assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.export(listOf(VideoSegment(0,1000)))};assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.prepare(clips(),"x".repeat(VideoCaptionWorksheet.LIMIT+1))}}
 @Test fun decodedUtf8ProjectTextLimitIsEnforcedWithoutChangingInputs(){val c=listOf(VideoSegment(0,100000,captions=List(100){i->VideoCaption(i*1000L,i*1000L+500,"original")}));val rows=VideoCaptionWorksheet.export(c).lines();val text=(listOf(rows[0])+rows.drop(1).map{it.substringBefore('\t')+"\t"+"漢".repeat(240)}).joinToString("\n");assertThrows(IllegalArgumentException::class.java){VideoCaptionWorksheet.prepare(c,text)};assertTrue(c[0].captions.all{it.text=="original"})}
 @Test fun completeMaximumCueWorksheetRoundTripsWithoutLosingUnchangedRows(){val c=List(5){VideoSegment(0,200000,captions=List(200){i->VideoCaption(i*1000L,i*1000L+500,"Text")})};val r=VideoCaptionWorksheet.prepare(c,VideoCaptionWorksheet.export(c).replace("1.1\tText","1.1\tTranslated"));assertEquals(1,r.changedCues);assertEquals(1000,r.clips.sumOf{it.captions.size})}
 @Test fun realProjectBatchApplyPreservesSoundtrackAndOneUndoRedoCodec(){val c=clips();val p=VideoEditProject(5000);val music=VideoSoundtrack("content://synthetic/music",10000,loop=false);p.restore(c,mapOf("other" to 5000L),music);val result=VideoCaptionWorksheet.prepare(c,changed(c),music);val request=VideoBatchReview(c,music);val stage=Any();request.open(stage);request.propose(stage,result.clips);assertTrue(request.apply(stage,p){});assertEquals(music,p.soundtrack);assertFalse(request.apply(stage,p){});assertTrue(p.undo());assertEquals(c,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(result.clips,p.segments);val draft=VideoDraft(5000,p.segments,0,0,0,5000,listOf(VideoSource("other","content://synthetic/video",5000)),music);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000))}
 @Test fun stalePausedForeignAndDismissedReviewsCannotReplaceCaptions(){for(mode in 0..3){val p=VideoEditProject(5000);val c=clips().take(1);p.restore(c);val request=VideoBatchReview(c,null);val stage=Any();request.open(stage);request.propose(stage,VideoCaptionWorksheet.prepare(c,changed(c)).clips);when(mode){0->{request.dismiss(stage);assertFalse(request.apply(stage,p){})};1->assertFalse(request.apply(Any(),p){});2->assertThrows(IllegalStateException::class.java){request.apply(stage,p){error("paused")}};3->{p.setTitle(0,"Changed");assertThrows(IllegalArgumentException::class.java){request.apply(stage,p){}}}};assertEquals("Hello",p.segments[0].captions[0].text)}}
}
